// Fixed-window request counter per key.
export function createLimiter({ limit, windowMs, now = Date.now }) {
  const counts = new Map()
  return {
    // true if the request is allowed
    check(key) {
      const window = Math.floor(now() / windowMs)
      const entry = counts.get(key)
      if (!entry || entry.window !== window) {
        counts.set(key, { window, count: 1 })
        return true
      }
      entry.count++
      return entry.count <= limit
    },
    // whole seconds until the given key's current window resets, rounded up, minimum 1
    retryAfterSeconds(key) {
      const entry = counts.get(key)
      if (!entry) return 1
      const resetAt = (entry.window + 1) * windowMs
      return Math.max(1, Math.ceil((resetAt - now()) / 1000))
    },
  }
}

