import { apiKeyOf } from './auth.js'

// req: { headers, ip }. Headers are lower-case, as Node gives them.
export function rateLimit(limiter) {
  return (req, res, next) => {
    if (req.headers['x-internal-health'] === '1') {
      next()
      return
    }
    const key = apiKeyOf(req) || req.ip
    if (!limiter.check(key)) {
      res.setHeader('Retry-After', String(limiter.retryAfterSeconds(key)))
      res.statusCode = 429
      res.end('Too Many Requests')
      return
    }
    next()
  }
}

