test('window resets after windowMs, not windowMs * 1000', () => {
  let time = 0
  const limiter = createLimiter({ limit: 1, windowMs: 1000, now: () => time })
  assert.equal(limiter.check('k'), true)
  time = 999
  assert.equal(limiter.check('k'), false, 'still within the same window')
  time = 1000
  assert.equal(limiter.check('k'), true, 'window has rolled over')
})

test('retryAfterSeconds rounds up and is never 0', () => {
  let time = 0
  const limiter = createLimiter({ limit: 1, windowMs: 1000, now: () => time })
  limiter.check('k')
  time = 1
  assert.equal(limiter.retryAfterSeconds('k'), 1)
  time = 999
