import { test } from 'node:test'
import assert from 'node:assert/strict'
import { rateLimit } from '../src/middleware.js'
import { createLimiter } from '../src/rateLimiter.js'

function req(headers = {}, ip = '1.1.1.1') {
  return { headers, ip }
}

function res() {
  const headers = {}
  return {
    headers,
    statusCode: 200,
    ended: false,
    body: undefined,
    setHeader(name, value) {
      headers[name] = value
    },
    end(body) {
      this.ended = true
      this.body = body
    },
  }
}

test('different api keys from the same IP get separate buckets', () => {
  const guard = rateLimit(createLimiter({ limit: 1, windowMs: 1000, now: () => 0 }))
  let calledA = false
  let calledB = false
  guard(req({ 'x-api-key': 'a' }), res(), () => { calledA = true })
  guard(req({ 'x-api-key': 'b' }), res(), () => { calledB = true })
  assert.equal(calledA, true)
  assert.equal(calledB, true)
})

test('key-less requests from the same IP share a bucket', () => {
  const guard = rateLimit(createLimiter({ limit: 1, windowMs: 1000, now: () => 0 }))
  const r1 = res()
  const r2 = res()
  guard(req({}, '9.9.9.9'), r1, () => {})
  guard(req({}, '9.9.9.9'), r2, () => {})
  assert.equal(r1.statusCode, 200)
  assert.equal(r2.statusCode, 429)
})

test('blocked requests get a Retry-After header, whole seconds, never 0', () => {
  const guard = rateLimit(createLimiter({ limit: 1, windowMs: 1000, now: () => 0 }))
  guard(req({ 'x-api-key': 'k' }), res(), () => {})
  const blocked = res()
  guard(req({ 'x-api-key': 'k' }), blocked, () => {})
  assert.equal(blocked.statusCode, 429)
  const retryAfter = Number(blocked.headers['Retry-After'])
  assert.ok(Number.isInteger(retryAfter) && retryAfter >= 1)
})

test('x-internal-health requests always pass, never counted', () => {
  const guard = rateLimit(createLimiter({ limit: 1, windowMs: 1000, now: () => 0 }))
  const healthReq = req({ 'x-internal-health': '1' }, '9.9.9.9')
  let passed = 0
  for (let i = 0; i < 5; i++) guard(healthReq, res(), () => { passed++ })
  assert.equal(passed, 5)
  // a normal request from the same IP still has its full quota
  const normal = res()
  guard(req({}, '9.9.9.9'), normal, () => {})
  assert.equal(normal.statusCode, 200)
})
